class Order:
    VAT_RATE = 0.12                      # class attribute, shared

    def __init__(self, order_id, customer):
        self.order_id = order_id          # instance attributes
        self.customer = customer
        self.lines = []

    def add_line(self, sku, qty, unit_price):
        if qty <= 0:
            raise ValueError(f"qty must be positive, got {qty}")
        self.lines.append((sku, qty, unit_price))

    def total(self):
        net = sum(q * p for _, q, p in self.lines)
        return round(net * (1 + self.VAT_RATE), 2)

    def __repr__(self):                   # used by print() and the REPL
        return f"Order({self.order_id}, {self.customer!r}, {len(self.lines)} lines)"

o1 = Order(1001, "Lindqvist Bakery")
o1.add_line("flour-25kg", 2, 18.50)
print(o1, o1.total())   # Order(1001, 'Lindqvist Bakery', 1 lines) 41.44

class Notifier:
    def send(self, to, text):
        raise NotImplementedError     # children must override

class EmailNotifier(Notifier):        # inheritance: is a Notifier
    def send(self, to, text):
        print(f"EMAIL to {to}: {text}")

class SmsNotifier(Notifier):
    def send(self, to, text):
        print(f"SMS to {to}: {text[:160]}")

class OrderService:
    def __init__(self, notifier: Notifier):
        self.notifier = notifier      # composition: has a Notifier

    def confirm(self, order, contact):
        self.notifier.send(contact, f"Order {order.order_id} confirmed")

OrderService(EmailNotifier()).confirm(o1, "orders@lindqvist.example")
OrderService(SmsNotifier()).confirm(o1, "+46 70 000 0000")

from dataclasses import dataclass, field
from datetime import date

@dataclass(frozen=True)
class Line:
    sku: str
    qty: int
    unit_price: float

@dataclass
class Order:
    order_id: int
    customer: str
    placed: date
    lines: list[Line] = field(default_factory=list)  # never lines=[]

    def total(self, vat: float = 0.12) -> float:
        return round(sum(l.qty * l.unit_price for l in self.lines) * (1 + vat), 2)

o = Order(1001, "Lindqvist Bakery", date(2026, 3, 2))
o.lines.append(Line("flour-25kg", 2, 18.50))
print(o)          # Order(order_id=1001, customer='Lindqvist Bakery', ...)
print(o.total())  # 41.44

import numpy as np

def expected_cost(y_true, scores, threshold, cost_fp, cost_fn):
    pred = scores >= threshold
    fp = np.sum(pred & (y_true == 0))
    fn = np.sum(~pred & (y_true == 1))
    return fp * cost_fp + fn * cost_fn, int(pred.sum())

def best_threshold(y_true, scores, cost_fp, cost_fn, max_flags=None):
    best = None
    for t in np.arange(0.05, 0.96, 0.05):
        cost, flags = expected_cost(y_true, scores, t, cost_fp, cost_fn)
        if max_flags is not None and flags > max_flags:
            continue                           # team cannot review this many
        if best is None or cost < best[1]:
            best = (round(t, 2), cost, flags)
    return best

